function renderResellerPicker(){const grid=$('#resellerPickerGrid');grid.innerHTML=resellerPickerItems.map((item,index)=>`<button type="button" class="reseller-picker-card ${String(resellerPickerSelected?.sourceId||'').split('::')[0]===String(item.id)?'active':''}" data-reseller-pick="${index}">${item._matchedVariant?.image||item.image?`<img loading="lazy" src="${esc(item._matchedVariant?.image||item.image)}" alt="">`:'<span class="reseller-picker-image">◈</span>'}<span><b>${esc(item.name)}</b><small>${item._matchedVariant?`Расцветка: ${esc(item._matchedVariant.name)}`:esc(item.price||item.details?.[0]||resellerCategoryNames[resellerPickerKind])}</small></span></button>`).join('')||'<div class="empty">Ничего не найдено</div>';$('#resellerPickerMore').hidden=!resellerPickerHasMore}
async function loadResellerPicker(append=false){
  const q=$('#resellerDealSearch').value.trim(),kind=resellerPickerKind;
  if(append&&resellerPickerLoading)return;
  const request=append?resellerPickerRequest:++resellerPickerRequest;
  if(!append){resellerPickerPage=1;resellerPickerItems=[];resellerPickerSelected=null;$('#resellerSelected').textContent='Сначала выберите позицию из списка'}
  resellerPickerLoading=true;
  $('#resellerPickerGrid').innerHTML='<div class="empty">Загружаю каталог…</div>';
  if(kind==='vehicles'){
    const items=(window.VEHICLE_CATALOG||[]).filter(x=>`${x.name} ${x.id}`.toLowerCase().includes(q.toLowerCase())).slice(0,240).map(x=>({...x,price:''}));
    if(request!==resellerPickerRequest||kind!==resellerPickerKind)return;
    resellerPickerItems=items;resellerPickerHasMore=false;resellerPickerLoading=false;renderResellerPicker();return;
  }
  const local=filterLocalCatalog(kind,q);
  if(local.length||readLocalCatalog()[kind]){resellerPickerItems=local.slice(0,400);resellerPickerHasMore=false;resellerPickerLoading=false;renderResellerPicker();warmLocalCatalog(kind);return}
  try{
    const page=1,data=await window.desktop.getWikiCatalog(kind,'',page);
    if(request!==resellerPickerRequest||kind!==resellerPickerKind||q!==$('#resellerDealSearch').value.trim())return;
    const store=readLocalCatalog();store[kind]={items:data.items||[],complete:!data.hasMore,nextPage:2,updatedAt:Date.now()};writeLocalCatalog(store);
    resellerPickerItems=filterLocalCatalog(kind,q).slice(0,400);resellerPickerHasMore=false;
    renderResellerPicker();
    warmLocalCatalog(kind);
  }catch(error){if(request===resellerPickerRequest)$('#resellerPickerGrid').innerHTML=`<div class="empty">Не удалось загрузить: ${esc(error?.message||'ошибка сети')}</div>`}
  finally{if(request===resellerPickerRequest)resellerPickerLoading=false}
}
